import type { SVGProps } from 'react';

export interface IconProps extends Omit<SVGProps<SVGSVGElement>, 'width' | 'height'> {
  /** Edge of the square box, in px. */
  size?: number | string;
}

/** A glyph is decoration by default: the text beside it already says what it means. */
const decorative = (rest: Omit<IconProps, 'size'>): true | undefined =>
  rest['aria-label'] === undefined && rest['aria-labelledby'] === undefined ? true : undefined;

const base = ({ size = 24, ...rest }: IconProps): SVGProps<SVGSVGElement> => ({
  xmlns: 'http://www.w3.org/2000/svg',
  width: size,
  height: size,
  viewBox: '0 0 24 24',
  fill: 'none',
  stroke: 'currentColor',
  strokeWidth: 2,
  strokeLinecap: 'round',
  strokeLinejoin: 'round',
  'aria-hidden': decorative(rest),
  ...rest,
});

/** The same box for a glyph drawn as a filled silhouette instead of a stroked outline. */
const solid = ({ size = 24, ...rest }: IconProps): SVGProps<SVGSVGElement> => ({
  xmlns: 'http://www.w3.org/2000/svg',
  width: size,
  height: size,
  viewBox: '0 0 24 24',
  fill: 'currentColor',
  'aria-hidden': decorative(rest),
  ...rest,
});

